28|type Remover interface {
29|	Remove(ctx context.Context, req removeclient.Request) error
30|}
31|
32|// Runner ties ES documents to MySQL, Mongo, and remove.
33|type Runner struct {
34|	UUID        UUIDResolver
35|	Mongo       DuvPicker
36|	Remove      Remover
37|	DstAreaType int64
38|	Mode        int64
39|	Stats       *Stats
40|	// OnRemoveFail is called when the remove HTTP call fails (after retries). Optional.
41|	OnRemoveFail func(uid, gid int64)
42|}
43|
44|// ProcessDoc returns skipReason empty on remove success; non-empty skip without error means skip path.
45|func (r *Runner) ProcessDoc(ctx context.Context, doc es.ScheduleDoc) (skipReason string, err error) {
46|	if r.Stats != nil {
47|		r.Stats.IncProcessed()
48|	}
49|	if doc.UID < 0 || doc.AreaType < 0 {
50|		return "", fmt.Errorf("pipeline: negative uid or area_type")
51|	}
52|	uid := uint64(doc.UID)
53|	area := uint64(doc.AreaType)
54|
55|	uuid, ok, err := r.UUID.GetUUID(ctx, uid, area)
56|	if err != nil {
57|		return "", err
58|	}
59|	if !ok {
60|		if r.Stats != nil {
61|			r.Stats.IncSkipNoUUID()
62|		}
63|		return SkipNoUUID, nil
64|	}
65|
66|	duv, pickOK, err := r.Mongo.PickForRemove(ctx, int64(uuid), doc.GID, doc.AreaType)
67|	if err != nil {
68|		return "", err
69|	}
70|	if !pickOK {
71|		if r.Stats != nil {
72|			r.Stats.IncSkipNotMaxDuv()
73|		}
74|		return SkipNotMaxDuv, nil
75|	}
76|
77|	req := removeclient.Request{
78|		UUID:             uuid,
79|		UgID:             doc.GID,
80|		DoneUnionVersion: duv,
81|		SrcAreaType:      doc.AreaType,
82|		DstAreaType:      r.DstAreaType,
83|		Mode:             r.Mode,
84|	}
85|	if err := r.Remove.Remove(ctx, req); err != nil {
86|		if r.OnRemoveFail != nil {
