88|		}
89|		if r.Stats != nil {
90|			r.Stats.IncRemoveFail()
91|		}
92|		return "", err
93|	}
94|	if r.Stats != nil {
95|		r.Stats.IncRemoveOK()
96|	}
97|	return "", nil
