14|// Fetcher loads schedule documents via search_after paging.
15|type Fetcher struct {
16|	Client          *elasticsearch.Client
17|	Index           string
18|	PageSize        int
19|	CreateTimeAfter string
20|}
21|
22|type searchRequest struct {
23|	Size        int           `json:"size"`
24|	Sort        []any         `json:"sort"`
25|	Query       map[string]any `json:"query"`
26|	SearchAfter []any         `json:"search_after,omitempty"`
27|}
28|
29|type searchResponse struct {
30|	Hits struct {
31|		Hits []struct {
32|			ID     string          `json:"_id"`
33|			Source ScheduleDoc     `json:"_source"`
34|			Sort   json.RawMessage `json:"sort"`
35|		} `json:"hits"`
36|	} `json:"hits"`
37|}
38|
39|// FetchPage returns the next page of documents and sort values for search_after (nil when no more pages).
40|func (f *Fetcher) FetchPage(ctx context.Context, searchAfter []any) ([]ScheduleDoc, []any, error) {
41|	if f.Client == nil {
42|		return nil, nil, fmt.Errorf("es: nil client")
43|	}
44|	if f.PageSize <= 0 {
45|		return nil, nil, fmt.Errorf("es: invalid page size")
46|	}
47|
48|	reqBody := searchRequest{
49|		Size: f.PageSize,
50|		Sort: []any{
51|			map[string]string{"create_time": "asc"},
52|			map[string]string{"_id": "asc"},
53|		},
54|		Query: map[string]any{
55|			"bool": map[string]any{
56|				"filter": []any{
57|					map[string]any{
58|						"terms": map[string]any{
59|							"state": []int64{4, 40},
60|						},
61|					},
62|					map[string]any{
63|						"range": map[string]any{
64|							"create_time": map[string]any{
65|								"gt": f.CreateTimeAfter,
66|							},
67|						},
68|					},
69|				},
70|			},
71|		},
72|		SearchAfter: searchAfter,
73|	}
74|	raw, err := json.Marshal(reqBody)
75|	if err != nil {
76|		return nil, nil, err
77|	}
78|
79|	res, err := f.Client.Search(
80|		f.Client.Search.WithContext(ctx),
81|		f.Client.Search.WithIndex(f.Index),
82|		f.Client.Search.WithBody(bytes.NewReader(raw)),
83|	)
84|	if err != nil {
85|		return nil, nil, err
86|	}
87|	defer res.Body.Close()
88|	body, err := io.ReadAll(res.Body)
89|	if err != nil {
90|		return nil, nil, err
91|	}
92|	if res.IsError() {
93|		return nil, nil, fmt.Errorf("es search: %s: %s", res.Status(), string(body))
94|	}
95|
96|	var parsed searchResponse
97|	if err := json.Unmarshal(body, &parsed); err != nil {
98|		return nil, nil, err
99|	}
100|	hits := parsed.Hits.Hits
101|	if len(hits) == 0 {
102|		return nil, nil, nil
103|	}
104|	docs := make([]ScheduleDoc, 0, len(hits))
105|	var next []any
106|	for i, h := range hits {
107|		docs = append(docs, h.Source)
108|		if i == len(hits)-1 && len(h.Sort) > 0 {
109|			if err := json.Unmarshal(h.Sort, &next); err != nil {
110|				return nil, nil, fmt.Errorf("decode sort: %w", err)
111|			}
112|		}
113|	}
114|	return docs, next, nil
115|}
116|
117|// NewClient builds an elasticsearch client from addresses (e.g. http://localhost:9200).
118|// Uses a custom transport that adds X-Elastic-Product when the server omits it, so calls
119|// work behind gateways and with clusters that do not send Elasticsearch product headers.
120|func NewClient(addresses []string) (*elasticsearch.Client, error) {
121|	return elasticsearch.NewClient(elasticsearch.Config{
122|		Addresses: addresses,
123|		Transport: &injectElasticProductHeader{base: http.DefaultTransport},
124|	})
