22|// PickForRemove returns duv and ok=true when (uu,ug) has at least one document:
23|// 取 duv 最大的一条（duv 逆序），duv 相同则按 mt、ut 最新。
24|func (s *Store) PickForRemove(ctx context.Context, uu, ug, areaType int64) (duv int64, ok bool, err error) {
25|	if s.coll == nil {
26|		return 0, false, fmt.Errorf("mongostore: nil collection")
27|	}
28|
29|	filter := bson.M{"uu": uu, "ug": ug}
30|	opts := options.FindOne().SetSort(bson.D{
31|		{Key: "duv", Value: -1},
32|		{Key: "mt", Value: -1},
33|		{Key: "ut", Value: -1},
34|	})
35|	var doc struct {
36|		Duv      int64 `bson:"duv"`
37|		AreaType int64 `bson:"a"`
38|	}
39|	err = s.coll.FindOne(ctx, filter, opts).Decode(&doc)
40|	if err == mongo.ErrNoDocuments {
41|		return 0, false, nil
42|	}
43|	if err != nil {
44|		return 0, false, err
45|	}
46|	if areaType != doc.AreaType {
47|		return 0, false, nil
48|	}
49|	return doc.Duv, true, nil
