2|
3|import (
4|	"bytes"
5|	"context"
6|	"encoding/json"
7|	"fmt"
8|	"io"
9|	"net/http"
10|	"time"
11|)
12|
13|// Request is the JSON body for /v1/uadispatch/remove.
14|type Request struct {
15|	UUID             uint64 `json:"uuid"`
16|	UgID             int64  `json:"ugid"`
17|	DoneUnionVersion int64  `json:"done_union_version"`
18|	SrcAreaType      int64  `json:"src_area_type"`
19|	DstAreaType      int64  `json:"dst_area_type"`
20|	Mode             int64  `json:"mode"`
21|}
22|
23|// Client calls the remove HTTP API with retries on server errors.
24|type Client struct {
25|	URL     string
26|	Timeout time.Duration
27|	Retries int
28|	HTTP    *http.Client
29|}
30|
31|// removeResponse matches the remove API envelope: success when ret.code == 0.
32|type removeResponse struct {
33|	Ret *struct {
34|		Code      int64  `json:"code"`
35|		Msg       string `json:"msg"`
36|		RequestID string `json:"request_id"`
37|	} `json:"ret"`
38|	Body struct {
39|		TaskID string `json:"task_id"`
40|	} `json:"body"`
41|}
42|
43|func checkRemoveResponse(statusCode int, raw []byte) error {
44|	if statusCode < 200 || statusCode >= 300 {
45|		return fmt.Errorf("remove: status %d: %s", statusCode, string(raw))
46|	}
47|	var out removeResponse
48|	if err := json.Unmarshal(raw, &out); err != nil {
49|		return fmt.Errorf("remove: decode response: %w (body=%s)", err, string(raw))
50|	}
51|	if out.Ret == nil {
52|		return fmt.Errorf("remove: missing ret in response: %s", string(raw))
53|	}
54|	if out.Ret.Code != 0 {
55|		return fmt.Errorf("remove: ret.code=%d msg=%q request_id=%q", out.Ret.Code, out.Ret.Msg, out.Ret.RequestID)
56|	}
57|	return nil
58|}
59|
60|// Remove POSTs the request body. Retries on 5xx and network errors until Retries exhausted (attempts = 1 + Retries).
61|// HTTP 2xx is not enough: the JSON body must have ret.code == 0.
62|func (c *Client) Remove(ctx context.Context, req Request) error {
63|	if c.URL == "" {
64|		return fmt.Errorf("removeclient: empty URL")
65|	}
66|	client := c.HTTP
67|	if client == nil {
68|		client = &http.Client{Timeout: c.Timeout}
69|	} else if c.Timeout > 0 && client.Timeout == 0 {
70|		client = &http.Client{
71|			Transport: client.Transport,
72|			Timeout:   c.Timeout,
73|		}
74|	}
75|
76|	body, err := json.Marshal(req)
77|	if err != nil {
78|		return err
79|	}
80|
81|	attempts := 1 + max(0, c.Retries)
82|	var lastErr error
83|	for i := 0; i < attempts; i++ {
84|		if i > 0 {
85|			select {
86|			case <-ctx.Done():
87|				return ctx.Err()
88|			case <-time.After(backoff(i)):
89|			}
90|		}
91|		httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.URL, bytes.NewReader(body))
92|		if err != nil {
93|			return err
94|		}
95|		httpReq.Header.Set("Content-Type", "application/json")
96|
97|		resp, err := client.Do(httpReq)
98|		if err != nil {
99|			lastErr = err
100|			continue
101|		}
102|		slurp, _ := io.ReadAll(resp.Body)
103|		resp.Body.Close()
104|
105|		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
106|			if err := checkRemoveResponse(resp.StatusCode, slurp); err != nil {
107|				lastErr = err
108|				// 业务码非 0 或 JSON 非法：不重试（与 4xx 一致）
109|				return lastErr
110|			}
111|			return nil
112|		}
113|
114|		lastErr = fmt.Errorf("remove: status %d: %s", resp.StatusCode, string(slurp))
115|		if resp.StatusCode < 500 {
116|			return lastErr
117|		}
118|	}
119|	if lastErr == nil {
120|		return fmt.Errorf("remove: unknown error")
121|	}
122|	return lastErr
123|}
124|
125|func backoff(attempt int) time.Duration {
126|	d := time.Duration(attempt) * 200 * time.Millisecond
127|	if d > 2*time.Second {
128|		return 2 * time.Second
129|	}
130|	return d
131|}
