8|// RunEnabled reports whether the worker should process work.
9|// If controlPath is empty, always true (no switch).
10|//
11|// Otherwise reads the file: first non-empty line (trimmed, lowercased):
12|//   pause: 0, off, no, pause, stop, false
13|//   run:   1, on, yes, run, true, empty line, or any other value
14|//
15|// If the file does not exist or cannot be read, defaults to run (true) so missing file keeps legacy behavior.
16|func RunEnabled(controlPath string) bool {
17|	if controlPath == "" {
18|		return true
19|	}
20|	data, err := os.ReadFile(controlPath)
21|	if err != nil {
22|		return true
23|	}
24|	line := ""
25|	for _, part := range strings.Split(string(data), "\n") {
26|		s := strings.TrimSpace(part)
27|		if s != "" {
28|			line = strings.ToLower(s)
29|			break
30|		}
31|	}
32|	switch line {
33|	case "0", "off", "no", "pause", "stop", "false":
34|		return false
35|	default:
36|		return true
37|	}
