12|// fileConfig is the YAML file layout (migrate.yaml).
13|type fileConfig struct {
14|	Elasticsearch struct {
15|		Addresses       []string `yaml:"addresses"`
16|		Address         string   `yaml:"address"` // optional: comma-separated URLs if addresses omitted
17|		Index           string   `yaml:"index"`
18|		CreateTimeAfter string   `yaml:"create_time_after"`
19|		PageSize        int      `yaml:"page_size"`
20|		MaxPages        int      `yaml:"max_pages"`
21|	} `yaml:"elasticsearch"`
22|
23|	MySQL struct {
24|		DSN string `yaml:"dsn"`
25|	} `yaml:"mysql"`
26|
27|	Mongo struct {
28|		URI        string `yaml:"uri"`
29|		Database   string `yaml:"database"`
30|		Collection string `yaml:"collection"`
31|	} `yaml:"mongo"`
32|
33|	Remove struct {
34|		URL         string `yaml:"url"`
35|		DstAreaType int64  `yaml:"dst_area_type"`
36|		Mode        int64  `yaml:"mode"`
37|		HTTPTimeout string `yaml:"http_timeout"`
38|		Retries     int    `yaml:"retries"`
39|	} `yaml:"remove"`
40|
41|	FailureLog          string `yaml:"failure_log"`
42|	ControlFile         string `yaml:"control_file"`
43|	ControlPollInterval string `yaml:"control_poll_interval"`
44|}
45|
46|// LoadFile reads and parses a YAML config file into Config.
47|func LoadFile(path string) (*Config, error) {
48|	raw, err := os.ReadFile(path)
49|	if err != nil {
50|		return nil, fmt.Errorf("config file %q: %w", path, err)
51|	}
52|	return ParseYAML(raw)
53|}
54|
55|// ParseYAML parses YAML bytes (for tests).
56|func ParseYAML(raw []byte) (*Config, error) {
57|	var f fileConfig
58|	if err := yaml.Unmarshal(raw, &f); err != nil {
59|		return nil, fmt.Errorf("config yaml: %w", err)
60|	}
61|
62|	addrs := f.Elasticsearch.Addresses
63|	if len(addrs) == 0 && strings.TrimSpace(f.Elasticsearch.Address) != "" {
64|		addrs = splitCommaURLs(f.Elasticsearch.Address)
65|	}
66|
67|	cfg := &Config{
68|		ESAddresses:           addrs,
69|		ESIndex:               strings.TrimSpace(f.Elasticsearch.Index),
70|		CreateTimeAfter:       strings.TrimSpace(f.Elasticsearch.CreateTimeAfter),
71|		PageSize:              f.Elasticsearch.PageSize,
72|		MaxPages:              f.Elasticsearch.MaxPages,
73|		MySQLDSN:              strings.TrimSpace(f.MySQL.DSN),
74|		MongoURI:              strings.TrimSpace(f.Mongo.URI),
75|		MongoDatabase:         strings.TrimSpace(f.Mongo.Database),
76|		MongoCollection:       strings.TrimSpace(f.Mongo.Collection),
77|		RemoveURL:             strings.TrimSpace(f.Remove.URL),
78|		DstAreaType:           f.Remove.DstAreaType,
79|		Mode:                  f.Remove.Mode,
80|		HTTPTimeout:           30 * time.Second,
81|		RemoveRetries:         3,
82|		ControlPollInterval:   time.Second,
83|		FailureLogPath:        strings.TrimSpace(f.FailureLog),
84|		ControlFilePath:       strings.TrimSpace(f.ControlFile),
85|	}
86|
87|	if cfg.PageSize <= 0 {
88|		cfg.PageSize = 1000
89|	}
90|	if strings.TrimSpace(f.Remove.HTTPTimeout) != "" {
91|		d, err := time.ParseDuration(strings.TrimSpace(f.Remove.HTTPTimeout))
92|		if err != nil {
93|			return nil, fmt.Errorf("remove.http_timeout: %w", err)
94|		}
95|		cfg.HTTPTimeout = d
96|	}
97|	if f.Remove.Retries > 0 {
98|		cfg.RemoveRetries = f.Remove.Retries
99|	}
100|	if strings.TrimSpace(f.ControlPollInterval) != "" {
101|		d, err := time.ParseDuration(strings.TrimSpace(f.ControlPollInterval))
102|		if err != nil {
103|			return nil, fmt.Errorf("control_poll_interval: %w", err)
104|		}
105|		cfg.ControlPollInterval = d
106|	}
107|
108|	if err := cfg.validate(); err != nil {
109|		return nil, err
110|	}
111|	return cfg, nil
112|}
113|
114|func splitCommaURLs(s string) []string {
115|	parts := strings.Split(s, ",")
116|	out := make([]string, 0, len(parts))
117|	for _, p := range parts {
118|		p = strings.TrimSpace(p)
119|		if p != "" {
120|			out = append(out, p)
121|		}
122|	}
123|	return out
124|}
