5|// injectElasticProductHeader wraps an HTTP transport so that successful responses
6|// missing X-Elastic-Product get Elasticsearch, satisfying go-elasticsearch/v8's
7|// product check (gateways / older clusters often omit the header).
8|type injectElasticProductHeader struct {
9|	base http.RoundTripper
10|}
11|
12|func (t *injectElasticProductHeader) RoundTrip(req *http.Request) (*http.Response, error) {
13|	base := t.base
14|	if base == nil {
15|		base = http.DefaultTransport
16|	}
17|	resp, err := base.RoundTrip(req)
18|	if err != nil || resp == nil {
19|		return resp, err
20|	}
21|	if resp.Header.Get("X-Elastic-Product") == "" {
22|		resp.Header.Set("X-Elastic-Product", "Elasticsearch")
23|	}
24|	return resp, nil
